function normalizeIcon(raw2) {
  const slug = (raw2 ?? "").trim().toLowerCase().replace(/^lucide:/, "");
  return KNOWN.has(slug) ? slug : FALLBACK;
}
function renderIcon(raw2, opts = {}) {
  const { size = 24, color = "#EE4B1A" } = opts;
  const slug = normalizeIcon(raw2);
  return ICON_SVGS[slug].replace('width="24"', `width="${size}"`).replace('height="24"', `height="${size}"`).replace('stroke="currentColor"', `stroke="${color}"`);
}

