import { createClient as createClient2 } from "@libsql/client";
var client = null;
var schemaReady = null;
function db() {
  if (!client) {
    client = createClient2({
      url: process.env.DATABASE_URL ?? "file:local-auth.db",
      authToken: process.env.DATABASE_AUTH_TOKEN
    });
  }
  return client;
}
function ensureSchema() {
  if (!schemaReady) {
    schemaReady = (async () => {
      await db().execute(`CREATE TABLE IF NOT EXISTS revision_memory (
        id TEXT PRIMARY KEY,
        user_id TEXT NOT NULL,
        draft_id TEXT NOT NULL,
        stage TEXT NOT NULL,
        request TEXT NOT NULL,
        outcome TEXT,
        created_at INTEGER NOT NULL
      )`);
      await db().execute(
        `CREATE INDEX IF NOT EXISTS idx_revision_memory_draft
         ON revision_memory(user_id, draft_id, created_at)`
      );
    })();
  }
  return schemaReady;
}
function rowToTurn(r) {
  return {
    id: String(r.id),
    userId: String(r.user_id),
    draftId: String(r.draft_id),
    stage: r.stage,
    request: String(r.request),
    outcome: r.outcome ?? null,
    createdAt: Number(r.created_at)
  };
}
var MAX_REMEMBERED_TURNS = 20;
async function appendRevision(input) {
  await ensureSchema();
  const now2 = Date.now();
  const id = crypto.randomUUID();
  await db().execute({
    sql: `INSERT INTO revision_memory (id, user_id, draft_id, stage, request, outcome, created_at)
          VALUES (?, ?, ?, ?, ?, ?, ?)`,
    args: [id, input.userId, input.draftId, input.stage, input.request, input.outcome ?? null, now2]
  });
  return {
    id,
    userId: input.userId,
    draftId: input.draftId,
    stage: input.stage,
    request: input.request,
    outcome: input.outcome ?? null,
    createdAt: now2
  };
}
async function listRevisions(userId, draftId, stage) {
  await ensureSchema();
  const res = await db().execute({
    sql: `SELECT * FROM revision_memory
          WHERE user_id = ? AND draft_id = ?${stage ? " AND stage = ?" : ""}
          ORDER BY rowid DESC
          LIMIT ?`,
    args: stage ? [userId, draftId, stage, MAX_REMEMBERED_TURNS] : [userId, draftId, MAX_REMEMBERED_TURNS]
  });
  return res.rows.map(rowToTurn).reverse();
}

