var import_cloudinary = __toESM(require_cloudinary2(), 1);
async function uploadImage(base64Data) {
  if (!process.env.CLOUDINARY_URL) {
    throw new Error("CLOUDINARY_URL environment variable is not configured");
  }
  const uploadStr = base64Data.startsWith("data:") ? base64Data : `data:image/jpeg;base64,${base64Data}`;
  const response = await import_cloudinary.v2.uploader.upload(uploadStr, {
    folder: "vourdev-carousels",
    resource_type: "image"
  });
  return response.secure_url;
}

// src/lib/publish/buffer.ts
async function scheduleBufferPost(params) {
  const token = process.env.BUFFER_TOKEN;
  if (!token) {
    throw new Error("BUFFER_TOKEN environment variable is not configured");
  }
  const query = `
    mutation CreatePost($input: CreatePostInput!) {
      createPost(input: $input) {
        ... on PostActionSuccess {
          post {
            id
            text
          }
        }
        ... on MutationError {
          message
        }
      }
    }
  `;
  const input = {
    text: params.text,
    channelId: params.channelId,
    schedulingType: "notification",
    mode: "customScheduled",
    dueAt: params.dueAt,
    saveToDraft: false,
    assets: params.assets.map((url2) => ({
      image: { url: url2 }
    }))
  };
  if (params.isTikTok) {
    if (params.title) {
      input.metadata = {
        tiktok: {
          title: params.title
        }
      };
    }
  } else {
    input.metadata = {
      instagram: {
        type: "post",
        shouldShareToFeed: true
      }
    };
  }
  const res = await fetch("https://api.buffer.com", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`
    },
    body: JSON.stringify({
      query,
      variables: { input }
    })
  });
  if (!res.ok) {
    throw new Error(`Buffer API returned HTTP ${res.status}: ${res.statusText}`);
  }
  const json3 = await res.json();
  if (json3.errors && json3.errors.length > 0) {
    throw new Error(`Buffer GraphQL Error: ${json3.errors[0].message}`);
  }
  const data = json3.data?.createPost;
  if (!data) {
    throw new Error("Buffer API returned empty data");
  }
  if (data.message) {
    throw new Error(`Buffer Creation Error: ${data.message}`);
  }
  const id = data.post?.id;
  if (!id) {
    throw new Error("Buffer did not return a post ID");
  }
  return id;
}

